package com.example;import org.springframework.web.bind.annotation.*;import java.util.List;@RestController @RequestMapping("/products") public class ProductController {private final ProductService svc;private final ProductRepository repo;public ProductController(ProductService s,ProductRepository r){svc=s;repo=r;}@GetMapping public List<Product> all(){return repo.findAll();}@GetMapping("/{id}") public Product one(@PathVariable Long id){return svc.getProduct(id);}}
